import { useState, type ReactNode } from "react"
import type { Icon } from "@/shared/ui/icon"
import type { Option } from "@/shared/ui/option-list"

/** 필터 하나: 무엇으로 거르는지와 고를 수 있는 값. 값이 하나라도 골라져야 걸린다(연산자 없음, 고른 것 중 하나). */
export type FilterDef<K extends string> = { key: K; label: string; icon: Icon; options: Option[]; isSearchable?: boolean }
/** 필터마다 고른 값. 비었으면 걸리지 않은 것이다. */
export type FilterState<K extends string> = Partial<Record<K, string[]>>

/**
 * 목록 페이지의 필터 상태(호호코워크 useFilters): 고른 값, 데스크톱 칩 줄에 보이는 필터(걸렸거나 막 더해 아직 빈 것),
 * 필터 메뉴(열림과 어느 필터의 값 단계인지). 무엇으로 거르는지(defs)는 페이지가 정한다.
 * 고른 값을 주소에 두려면 state · onStateChange를 넘긴다(lib/list-address의 useAddressFilters). 칩 줄에는 걸린 필터가 늘 보인다.
 */
export function useFilters<K extends string>(defs: readonly FilterDef<K>[], controlled?: {
  state: FilterState<K>; onStateChange: (next: FilterState<K>) => void
}) {
  const [ownState, setOwnState] = useState<FilterState<K>>({})
  const state = controlled?.state ?? ownState
  const setState = (update: (current: FilterState<K>) => FilterState<K>) => {
    if (controlled) controlled.onStateChange(update(controlled.state))
    else setOwnState(update)
  }
  const [ownShown, setShown] = useState<K[]>([])
  // 주소에서 온 조건은 칩 줄에 늘 보인다(막 더해 아직 빈 필터는 화면 상태로 덧붙는다).
  const applied = defs.filter(def => (state[def.key]?.length ?? 0) > 0).map(def => def.key)
  const shown = [...applied.filter(key => !ownShown.includes(key)), ...ownShown]
  const [menu, setMenu] = useState<{ isOpen: boolean; step?: K }>({ isOpen: false })
  const show = (key: K) => setShown(current => (current.includes(key) ? current : [...current, key]))
  const change = (key: K, values: string[]) => {
    setState(current => ({ ...current, [key]: values }))
    if (values.length > 0) show(key)
  }
  const defOf = (key: K) => defs.find(def => def.key === key)!
  return {
    defs, state, shown, menu, setMenu, change, show, defOf,
    /** 걸린 필터. */
    active: defs.filter(def => (state[def.key]?.length ?? 0) > 0).map(def => def.key),
    /** 고른 값 이름: 둘까지 보이고 나머지는 +N. */
    chosenNames: (key: K) => {
      const names = (state[key] ?? []).map(value => defOf(key).options.find(option => option.value === value)?.label ?? value)
      return { shown: names.slice(0, 2).join(", "), more: Math.max(0, names.length - 2) }
    },
    remove: (key: K) => { change(key, []); setShown(current => current.filter(each => each !== key)) },
    clear: () => { setState(() => ({})); setShown([]) },
  }
}

export type Filters<K extends string> = ReturnType<typeof useFilters<K>>
/** 필터 값 옆에 그리는 표식(아이콘 · 아바타 · 색 점). */
export type FilterMark = ReactNode

import { toggleValue } from "@/shared/lib/toggle"
import { useIsMobile } from "@/shared/lib/use-mobile"
import { AdaptivePopover } from "@/shared/ui/adaptive-popover"
import { Button } from "@/shared/ui/button"
import { ArrowLeftIcon, ChevronRightIcon, ListFilterIcon } from "@/shared/ui/icon"
import { OptionList } from "@/shared/ui/option-list"
import { ToolDot } from "@/shared/ui/page"
import type { Filters } from "./use-filters"

/**
 * 필터 도구(호호코워크 FilterMenu · FilterSheet): 동그란 버튼이 필터 목록을 먼저 열고, 고르면 그 필터의 값으로 바뀐다.
 * 머리의 ← 가 목록으로 돌아간다. 데스크톱은 팝오버, 휴대폰은 바텀시트(목록마다 고른 값 요약과 >, 아래 완료).
 * 필터가 걸려 있으면 귀퉁이에 점이 있고 아이콘은 Bold Duotone이다.
 */
export function FilterMenu<K extends string>({ filters }: { filters: Filters<K> }) {
  const isMobile = useIsMobile()
  const { menu, setMenu, state, active } = filters
  const isOn = menu.isOpen || active.length > 0
  const step = menu.step ? filters.defOf(menu.step) : undefined
  const open = (key: K) => {
    setMenu({ isOpen: true, step: key })
    if (!isMobile) filters.show(key)
  }
  const done = (
    <div className="flex justify-end pt-3">
      {/* 휴대폰의 짧은 실행 단추는 44px 높이에 88px 이상 너비(spacing.md). */}
      <Button variant="secondary" size="lg" className="h-11 min-w-22 rounded-full px-5" onClick={() => setMenu({ isOpen: false })}>완료</Button>
    </div>
  )
  return (
    <AdaptivePopover title="필터" align="end" className="w-65 p-1.5"
      open={menu.isOpen} onOpenChange={isOpen => setMenu({ isOpen })}
      trigger={
        <Button variant={isOn ? "view-active" : "tool"} size="icon" aria-label={active.length > 0 ? `필터, ${active.length}개 적용 중` : "필터"}
          className="relative max-md:size-11">
          <ListFilterIcon chosen={isOn} />
          {active.length > 0 && <ToolDot label="필터 적용 중" />}
        </Button>
      }>
      {step ? (
        <div className="flex flex-col">
          <div className="flex items-center gap-1.5 border-b px-1 pb-2 font-semibold">
            <Button variant="ghost" size="icon-sm" aria-label="필터 목록으로" onClick={() => setMenu({ isOpen: true })}>
              <ArrowLeftIcon />
            </Button>
            <step.icon className="shrink-0" />
            {step.label}
          </div>
          <OptionList label={`${step.label} 고르기`} isSearchable={step.isSearchable} options={step.options} chosen={state[step.key]}
            onPick={value => filters.change(step.key, toggleValue(state[step.key], value))} />
          {isMobile && done}
        </div>
      ) : (
        <div className="flex flex-col">
          <OptionList label="필터" isSearchable={!isMobile} chosen={isMobile ? [] : active}
            options={filters.defs.map(def => {
              const names = filters.chosenNames(def.key)
              return {
                value: def.key, label: def.label, icon: <def.icon />,
                end: isMobile ? (
                  <span className="flex items-center gap-1 text-muted-foreground">
                    {names.shown || "전체"}{names.more > 0 && ` +${names.more}`}
                    <ChevronRightIcon />
                  </span>
                ) : undefined,
              }
            })}
            onPick={key => open(key as K)} />
          {isMobile && done}
        </div>
      )}
    </AdaptivePopover>
  )
}

import { useState } from "react"
import { toggleValue } from "@/shared/lib/toggle"
import { Button } from "@/shared/ui/button"
import { PlusIcon, XIcon } from "@/shared/ui/icon"
import { OptionList } from "@/shared/ui/option-list"
import { Popover, PopoverContent, PopoverTrigger } from "@/shared/ui/popover"
import type { Filters } from "./use-filters"

/**
 * 데스크톱 툴바 아래 걸린 필터 줄(호호코워크 FilterBar, 40px): 필터마다 [이름 | 값 | ×] 칩, 아직 없는 필터를 더하는 +,
 * 걸린 것이 있으면 모두 지우기. 값 칸은 그 필터의 값을 연다. 한 번에 메뉴 하나만 열린다. 보이는 필터가 없으면 그리지 않는다.
 */
export function FilterBar<K extends string>({ filters }: { filters: Filters<K> }) {
  const [opened, setOpened] = useState<K | "+">()
  if (filters.shown.length === 0) return null
  const unused = filters.defs.filter(def => !filters.shown.includes(def.key))
  const openChange = (key: K | "+") => (isOpen: boolean) => setOpened(isOpen ? key : undefined)
  return (
    <div data-slot="filter-bar" className="flex h-10 shrink-0 items-center gap-1.5 overflow-x-auto border-b px-4 [scrollbar-width:none]">
      {filters.shown.map(key => {
        const def = filters.defOf(key)
        const names = filters.chosenNames(key)
        return (
          <div key={key} role="group" aria-label={`${def.label} 필터`}
            className="flex h-6 shrink-0 items-stretch divide-x divide-input overflow-hidden rounded-full border border-input bg-background text-xs">
            <span className="flex items-center gap-1 px-2 text-muted-foreground"><def.icon className="size-3.5" />{def.label}</span>
            <Popover open={opened === key} onOpenChange={openChange(key)}>
              <PopoverTrigger className="flex items-center gap-1 px-2 hover:bg-accent aria-expanded:bg-accent">
                {names.shown || <span className="text-muted-foreground">--</span>}
                {names.more > 0 && <span className="text-muted-foreground">+{names.more}</span>}
              </PopoverTrigger>
              <PopoverContent align="start" aria-label={`${def.label} 고르기`} className="w-65 p-1.5">
                <OptionList label={`${def.label} 고르기`} isSearchable={def.isSearchable} options={def.options} chosen={filters.state[key]}
                  onPick={value => filters.change(key, toggleValue(filters.state[key], value))} />
              </PopoverContent>
            </Popover>
            <button type="button" aria-label={`${def.label} 필터 지우기`} onClick={() => filters.remove(key)}
              className="flex items-center px-1.5 text-muted-foreground hover:bg-accent hover:text-foreground">
              <XIcon className="size-3.5" />
            </button>
          </div>
        )
      })}
      {unused.length > 0 && (
        <Popover open={opened === "+"} onOpenChange={openChange("+")}>
          <PopoverTrigger render={<Button variant="ghost" size="icon-xs" aria-label="필터 추가" />}>
            <PlusIcon />
          </PopoverTrigger>
          <PopoverContent align="start" aria-label="필터 추가" className="w-60 p-1.5">
            <OptionList label="필터 추가" isSearchable options={unused.map(def => ({ value: def.key, label: def.label, icon: <def.icon /> }))}
              onPick={key => { filters.show(key as K); setOpened(key as K) }} />
          </PopoverContent>
        </Popover>
      )}
      {filters.active.length > 0 && <Button variant="secondary" size="xs" className="rounded-full" onClick={filters.clear}>모두 지우기</Button>}
    </div>
  )
}

/** 휴대폰 툴바 아래 걸린 필터 칩(가로로 넘김). 칩을 누르면 시트가 그 필터에서 열리고, ×가 뗀다. */
export function FilterChips<K extends string>({ filters }: { filters: Filters<K> }) {
  if (filters.active.length === 0) return null
  return (
    <div data-slot="filter-chips" className="flex shrink-0 items-center gap-1.5 overflow-x-auto border-b px-4 py-2 [scrollbar-width:none]">
      {filters.active.map(key => {
        const def = filters.defOf(key)
        const names = filters.chosenNames(key)
        return (
          <div key={key} className="flex h-11 shrink-0 items-center rounded-full bg-secondary pl-3 text-sm">
            <button type="button" className="flex h-full items-center gap-1 px-1" onClick={() => filters.setMenu({ isOpen: true, step: key })}>
              <b className="font-semibold">{def.label}</b>
              {names.shown}
              {names.more > 0 && <span className="text-muted-foreground">+{names.more}</span>}
            </button>
            <Button variant="ghost" size="icon" aria-label={`${def.label} 필터 지우기`} className="size-11 rounded-full" onClick={() => filters.remove(key)}>
              <XIcon />
            </Button>
          </div>
        )
      })}
    </div>
  )
}
